2	(function () {
3	  "use strict";
4	
5	  const L = window.LooksmaxLogic;
6	  const ROUNDS = window.LOOKSMAX_ROUNDS;
7	
8	  const app = document.getElementById("app");
9	  const coinsEl = document.getElementById("coins");
10	  const progressEl = document.getElementById("progress");
11	  const announcer = document.getElementById("announcer");
12	
13	  let state = L.createGame(ROUNDS);
14	  let lastVerdict = "";
15	  let cart = { status: "idle" };
16	
17	  // --- помощники -----------------------------------------------------------
18	
