76	    const ticks = state.rounds.map((_, i) => {
77	      const pick = state.picks[i];
78	      let cls = "tick";
79	      if (pick) cls += pick.correct ? " tick--hit" : " tick--miss";
80	      if (i === state.index) cls += " tick--now";
81	      return h("li", { class: cls });
82	    });
83	    progressEl.replaceChildren(
84	      h("p", { class: "bar__round" }, `Раунд ${state.index + 1} из ${state.rounds.length}`),
85	      h("ol", { class: "ticks", "aria-hidden": "true" }, ticks),
