171	  function controls() {
172	    const pick = L.currentPick(state);
173	    if (pick) {
174	      return h("div", { class: "controls controls--after" }, [
175	        h("p", { class: pick.correct ? "verdict verdict--hit" : "verdict verdict--miss" }, lastVerdict),
176	        h("button", { class: "btn btn--next", type: "button", id: "next", onclick: onNext }, "Дальше"),
177	      ]);
178	    }
179	
180	    let note;
181	    if (L.removedId(state) !== null) note = "Один неверный вариант убран. Выбирай из двух.";
182	    else if (state.coins < L.HINT_COST)
183	      note = `Нужно ${L.HINT_COST} коинов, у тебя ${state.coins}. Коины дают за верные ответы.`;
