185	
186	    return h("div", { class: "controls" }, [
187	      h(
188	        "button",
189	        {
190	          class: "btn btn--hint",
191	          type: "button",
192	          disabled: !L.canUseHint(state),
193	          "aria-describedby": "hint-note",
194	          onclick: onHint,
195	        },
196	        `Мьюинг за ${L.HINT_COST} ${coinsWord(L.HINT_COST)}`,
197	      ),
198	      h("p", { class: "controls__note", id: "hint-note" }, note),
199	    ]);
200	  }
201	
202	  function renderRound() {
203	    const r = round();
204	    app.replaceChildren(
205	      h("section", { class: "round", "aria-labelledby": "round-title" }, [
206	        h("div", { class: "round__head" }, [
207	          h("h1", { class: "round__title", id: "round-title", tabindex: "-1" }, capital(r.query)),
208	          h("p", { class: "round__ask" }, [
209	            "Кто здесь могает по белку? Выбери товар, где больше калорий приходится на белок. ",
210	            h("span", { class: "round__formula" }, "Скор = белки × 4 / ккал, рост на стене."),
211	          ]),
212	        ]),
213	        h("div", { class: "lineup" }, [
214	          scale(),
215	          h("ul", { class: "lineup__slots", "aria-label": "Три товара" }, r.products.map(slot)),
216	        ]),
217	        controls(),
218	      ]),
219	    );
220	  }
221	
222	  // --- итог ----------------------------------------------------------------
223	
224	  function ladder(rank, percent) {
225	    const rungs = L.RANKS.map((r, i) => {
226	      const next = L.RANKS[i + 1];
227	      const range = next ? `${r.from}–${next.from - 1}%` : `${r.from}%`;
228	      const mine = r.name === rank;
229	      return h("li", { class: mine ? "rung rung--you" : "rung", "aria-current": mine ? "true" : null }, [
230	        h("span", { class: "rung__name" }, r.name),
231	        h("span", { class: "rung__range" }, range),
232	        mine ? h("span", { class: "rung__you" }, `ты, ${percent}%`) : null,
233	      ]);
234	    }).reverse();
235	    return h("ol", { class: "ladder", "aria-label": "Лестница рангов от true adam до sub3" }, rungs);
236	  }
237	
238	  function cartBlock(result) {
239	    const picks = state.picks.map((pick, i) => {
240	      const p = productById(state.rounds[i], pick.productId);
241	      return h("li", { class: pick.correct ? "pick pick--hit" : "pick pick--miss" }, [
242	        h("span", { class: "pick__mark" }, pick.correct ? "верно" : "мимо"),
243	        h("span", { class: "pick__name" }, p.name),
244	        h("span", { class: "pick__price" }, rub(p.price)),
245	      ]);
246	    });
247	    const total = state.picks.reduce(
248	      (sum, pick, i) => sum + productById(state.rounds[i], pick.productId).price,
249	      0,
250	    );
251	
252	    let status = null;
253	    if (cart.status === "done") {
254	      status = h("p", { class: "cart__status cart__status--done" }, [
255	        "Корзина собрана. ",
256	        h("a", { href: cart.link, target: "_blank", rel: "noopener" }, "Открыть корзину во ВкусВилле"),
257	        h("span", { class: "cart__link" }, cart.link),
258	      ]);
259	    } else if (cart.status === "error") {
260	      status = h("p", { class: "cart__status cart__status--error" }, [
261	        h("strong", {}, "Корзину собрать не получилось. "),
262	        cart.error.replace(/\.?$/, ". "),
263	        "Результат игры никуда не делся.",
264	      ]);
265	    }
266	
267	    return h("section", { class: "cart", "aria-labelledby": "cart-title" }, [
268	      h("h2", { id: "cart-title" }, "Твоя корзина"),
269	      h("p", { class: "cart__lead" }, `Твои выборы за ${result.total} раундов, по одной штуке каждого.`),
270	      h("ol", { class: "picks" }, picks),
271	      h("p", { class: "cart__total" }, ["Итого ", h("strong", {}, rub(total))]),
272	      cart.status === "done"
273	        ? null
274	        : h(
275	            "button",
276	            {
277	              class: "btn btn--cart",
278	              type: "button",
279	              id: "cart-button",
280	              disabled: cart.status === "loading",
281	              onclick: () => onCart(result.xmlIds),
282	            },
283	            cart.status === "loading" ? "Собираем корзину…" : "Собрать корзину во ВкусВилле",
284	          ),
285	      h("div", { class: "cart__live", "aria-live": "polite" }, status),
286	    ]);
287	  }
288	
289	  function renderResult() {
290	    const result = L.summary(state);
291	    app.replaceChildren(
292	      h("section", { class: "result", "aria-labelledby": "result-title" }, [
293	        h("div", { class: "result__head" }, [
294	          h("p", { class: "result__lead" }, "Твой ранг"),
295	          h("h1", { class: "result__rank", id: "result-title", tabindex: "-1" }, result.rank),
296	          h("p", { class: "result__stats" }, [
297	            h("strong", {}, `${result.percent}%`),
298	            ` верных: ${result.correct} из ${result.total}. На счету ${result.coins} ${coinsWord(result.coins)}.`,
299	          ]),
300	          h("button", { class: "btn btn--ghost", type: "button", onclick: onRestart }, "Сыграть ещё раз"),
301	        ]),
302	        ladder(result.rank, result.percent),
303	        cartBlock(result),
304	      ]),
305	    );
306	  }
307	
308	  function render() {
309	    renderBar();
310	    if (L.isFinished(state)) renderResult();
311	    else renderRound();
312	  }
313	
314	  // --- действия ------------------------------------------------------------
315	
316	  function onChoose(id) {
317	    const before = state.coins;
318	    state = L.choose(state, id);
319	    const r = state.rounds[state.index];
320	    const pick = L.currentPick(state);
321	    const gain = state.coins - before;
322	    const winner = productById(r, r.winner_id);
323	    if (pick.correct) {
324	      lastVerdict = state.streak >= 3
325	        ? `Мог. Серия ${state.streak} подряд: +${gain} ${coinsWord(gain)}.`
326	        : `Мог. Лучший скор раунда: +${gain} ${coinsWord(gain)}.`;
327	    } else {
328	      lastVerdict = `Мимо. Лучший скор у «${winner.name}»: ${num(winner.score, 3)}.`;
329	    }
330	    render();
331	    announce(lastVerdict);
332	    document.getElementById("next").focus();
333	  }
334	
335	  function onHint() {
336	    state = L.useHint(state);
337	    const removed = productById(round(), L.removedId(state));
338	    render();
339	    announce(`Мьюинг убрал «${removed.name}». Осталось ${state.coins} ${coinsWord(state.coins)}.`);
340	    app.querySelector(".card:not(:disabled)").focus();
341	  }
342	
343	  function onNext() {
344	    state = L.nextRound(state);
345	    render();
346	    const title = document.getElementById(L.isFinished(state) ? "result-title" : "round-title");
347	    title.focus();
348	    window.scrollTo({ top: 0 });
349	  }
350	
351	  async function onCart(xmlIds) {
352	    cart = { status: "loading" };
353	    render();
354	    try {
355	      const link = await L.requestCartLink(xmlIds, window.fetch.bind(window));
356	      cart = { status: "done", link: link };
357	    } catch (e) {
358	      cart = { status: "error", error: e.message };
359	    }
360	    render();
361	    const focusTarget = cart.status === "done"
362	      ? app.querySelector(".cart__status a")
363	      : document.getElementById("cart-button");
364	    focusTarget.focus();
365	  }
366	
367	  function onRestart() {
368	    state = L.createGame(ROUNDS);
369	    cart = { status: "idle" };
370	    render();
371	    document.getElementById("round-title").focus();
372	  }
373	
374	  if (!Array.isArray(ROUNDS) || ROUNDS.length === 0) {
375	    app.replaceChildren(
376	      h("p", { class: "note" }, "Нет раундов: собери их командой python scripts/build_rounds.py."),
377	    );
378	    return;
379	  }
380	  render();
381	})();
